selector_to_html = {"a[href=\"AreaLaw.html#pyskyfire.ducts.area_law.AreaLaw\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.area_law.AreaLaw\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.area_law.</span></span><span class=\"sig-name descname\"><span class=\"pre\">AreaLaw</span></span></dt><dd><p>Bases: <a class=\"reference external\" href=\"https://docs.python.org/3/library/abc.html#abc.ABC\" title=\"(in Python v3.15)\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">abc.ABC</span></code></a></p><p>A rule relating azimuth to passage size.</p></dd>", "a[href=\"ConstantAngularMomentum.html#pyskyfire.ducts.area_law.ConstantAngularMomentum\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.area_law.ConstantAngularMomentum\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.area_law.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ConstantAngularMomentum</span></span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">AreaLaw</span></code></p><p>Size the passage to conserve the angular momentum it collects.</p><p>Imposing <code class=\"docutils literal notranslate\"><span class=\"pre\">(r*C_u)_c</span> <span class=\"pre\">=</span> <span class=\"pre\">(r*C_u)_5</span></code> together with mass conservation gives\nAungier\u2019s Eqs. 11-1 to 11-3, generalised by the sizing parameter in\nEq. 11-5:</p><p>so the area divided by the centroid radius grows linearly with azimuth.\nBecause both <code class=\"docutils literal notranslate\"><span class=\"pre\">A</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">r_c</span></code> follow from the section size, this is\nimplicit in the size and is solved rather than evaluated.</p></dd>", "a[href=\"#module-pyskyfire.ducts.area_law\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.area_law<a class=\"headerlink\" href=\"#module-pyskyfire.ducts.area_law\" title=\"Link to this heading\">\u00b6</a></h1><p>Rules that set how a volute cross-section grows with azimuth.</p><p>An area law answers one question: at polar angle <code class=\"docutils literal notranslate\"><span class=\"pre\">theta</span></code> measured from the\ntongue, how big should the passage be? It answers it as a residual rather than\nas an area, because the shaped laws constrain the area <em>and</em> the centroid\nradius together, and both follow from the section size. The volute solver\ndrives that residual to zero.</p>", "a[href=\"#references\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">References<a class=\"headerlink\" href=\"#references\" title=\"Link to this heading\">\u00b6</a></h2><p>Aungier, R. H., <em>Centrifugal Compressors: A Strategy for Aerodynamic Design and\nAnalysis</em>, ASME Press, 2000, Chapter 11.</p>", "a[href=\"ConstantArea.html#pyskyfire.ducts.area_law.ConstantArea\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.area_law.ConstantArea\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.area_law.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ConstantArea</span></span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">AreaLaw</span></code></p><p>Hold the passage area uniform all the way around.</p><p>This is Aungier\u2019s \u201ccollector\u201d rather than a volute. It collects the flow\nwithout conserving angular momentum, so its sizing parameter is whatever\nthe chosen area happens to produce and its tangential-velocity loss is\ncorrespondingly larger. Aungier\u2019s Eq. 5-108 additionally averages that loss\nagainst a total loss of tangential head, because a uniform passage tries to\ndiffuse the entering flow to rest where collection begins.</p></dd>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"VoluteInlet.html#pyskyfire.ducts.area_law.VoluteInlet\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.area_law.VoluteInlet\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.area_law.</span></span><span class=\"sig-name descname\"><span class=\"pre\">VoluteInlet</span></span></dt><dd><p>Flow conditions and placement at the volute inlet, Aungier\u2019s station 5.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
